### 1. Using the `JSONSerialization` class

The `JSONSerialization` class in iOS provides a way to convert raw JSON strings into Swift objects, including dictionaries and arrays.

```swift
import Foundation

func loadJson() -> [String: Any]? {
    guard let data = try? Data(contentsOf: URL(fileURLWithPath: "/path/to/your/json/file.json")) else { return nil }

    do {
        let json = try JSONSerialization.jsonObject(with: data, options: []) as? [[String: Any]]
        return json
    } catch {
        print("Error parsing JSON: \(error)")
        return nil
    }
}

// Example of using the function to load a list of dictionaries:
if let jsonData = loadJson() {
    guard let jsonArray = jsonData else { return }

    for item in jsonArray {
        // Each dictionary in the array represents an object and can be accessed with its key.
        print(item["key1"] as? String)  // Accessing "key1"
        print(item["anotherKey"].boolValue ?? false)  // Accessing a boolean value
    }
}
```

### 2. Using `KeyedDecodingContainer` or `Decoder`

If you have more complex JSON structures with nested objects, you might need to use the `Decoder`. This is useful for parsing custom data types.

```swift
import Foundation

struct Person: Decodable {
    let name: String
    let age: Int

    enum CodingKeys: String, CodingKey { case name = "name", age = "age" }
}

func decodeJson() -> [Person]? {
    guard let path = Bundle.main.path(forResource: "jsonData", ofType: "json") else { return nil }

    do {
        let data = try Data(contentsOf: URL(fileURLWithPath: path))

        var decoder = JSONDecoder()
        let container = try decoder.decode([Person].self, from: data)

        if let jsonArray = container as? [[Person]] {
            return jsonArray
        }
    } catch {
        print("Error decoding JSON: \(error)")
    }

    return nil
}

// Example of using the function to decode an array of `Person` objects:
if let json = decodeJson() {
    for person in json {
        print(person.name, person.age)
    }
}
```

### 3. Using `Codable` Protocol

If your JSON is a representation of Swift classes or structures that conform to the `Codable` protocol, you can use it directly.

```swift
import Foundation

struct Person: Codable {
    let name: String?
    let age: Int?

    enum CodingKeys: String, CodingKey { case name = "name", age = "age" }
}

