```swift
func fetchPeopleData() {
    guard let url = Bundle.main.url(forResource: "people", withExtension: "json") else {
        return
    }

    URLSession.shared.dataTask(with: url) { (data, response, error) in
        if let data = data,
           let strData = String(data: data, encoding: .utf8) {
