let values = vec![5, 8, 2, 9, 1];
let min_value = find_min_value(values);
println!("The minimum value is {}", min_value); // Output: The minimum value is 1
```

### Using `std::cmp` and `min`

If you prefer to use Rust's standard library, you can also achieve this by manually comparing elements.

```rust
fn find_min_value(arr: &[i32]) -> i32 {
    arr.iter().cloned().min().unwrap_or_default()
}

// Example usage:
let values = [5, 8, 2, 9, 1];
let min_value = find_min_value(&values);
println!("The minimum value is {}", min_value); // Output: The minimum value is 1
```

### Using `std::collections::BinaryHeap` (for vectors)

If you need to optimize for a vector of integers where memory efficiency is crucial, consider using the `BinaryHeap`, which can be used as an underlying data structure.

```rust
use std::collections::BinaryHeap;

fn find_min_value(arr: Vec<i32>) -> i32 {
    let mut min_heap = BinaryHeap::from(arr);
    if min_heap.is_empty() {
        panic!("Vector cannot be empty");
    }
    match min_heap.peek().cloned() {
        Some(&value) => value,
        None => unreachable!(),
    }
}

// Example usage:
