         { id: 2, title: 'Post 2', body: 'Content of post 2' }
       ]
     },

     Mutation: {
       createUser: (parent, args) => {
         return { id: 3, name: 'New User', email: 'newuser@example.com' };
       }
     },
   };

   module.exports = resolvers;
   ```

5. **Create a Server Using Express**: Use the `express` framework to set up your GraphQL server.

