   app.use(bodyParser.urlencoded({ extended: false }));
   app.use(bodyParser.json());

   const resolvers = require('./resolvers');

   const queryResolvers = Object.keys(resolvers.Query).reduce((acc, key) => {
     acc[key] = (...args) => resolvers.Query[key](null, args);
     return acc;
   }, {});

   // Set up GraphQL endpoint
   app.use('/graphql', (req, res) => {
     const result = { query: req.query.q || null };
     if (result.query && typeof resolvers.Query[result.query] !== 'undefined') {
       try {
         const data = resolvers.Query[result.query](null, [result]);
         return res.status(200).json(data);
       } catch (e) {
         return res.status(400).json({ error: e.message || 'Invalid query' });
       }
     }

     res.status(400).send('Invalid query');
   });

   app.listen(port, () => console.log(`Running at http://localhost:${port}/graphql`));
   ```

6. **Test Your GraphQL Server**: You can now access your GraphQL server using a tool like `https://www.graphql-playground.com/`, or by navigating to `http://localhost:4000/graphql` in your browser.

That’s it! You have set up a basic Node.js Express-based GraphQL API. Now you can use this as a starting point for more complex, server-side rendered applications and integrations with databases using ORM libraries like Sequelize.

