    while (l1.head != nullptr && l2.head != nullptr) {
        if (l1.head->data != l2.head->data)
            return false;
        l1.head = l1.head->next;
        l2.head = l2.head->next;
    }
    return l1.head == nullptr && l2.head == nullptr;
}

